-- Let signed-in users delete only their own saved drafts.
drop policy if exists "Authenticated users can delete own drafts" on public.drafts;
create policy "Authenticated users can delete own drafts"
  on public.drafts for delete to authenticated
  using ((select auth.uid()) = user_id);
grant delete on table public.drafts to authenticated;

-- Restrict draft creation to editable content and ownership; ids and timestamps
-- should always be generated by Postgres.
revoke insert on table public.drafts from authenticated;
grant insert (user_id, original_message, situation, tone, generated_reply, desired_outcome, avoid)
  on table public.drafts to authenticated;

-- Make the server-only payment matching table explicitly deny client roles.
drop policy if exists "No client access to unmatched sales" on public.gumroad_unmatched_sales;
create policy "No client access to unmatched sales"
  on public.gumroad_unmatched_sales for all to anon, authenticated
  using (false)
  with check (false);

-- Remove public from the quota function's object-resolution search path.
create or replace function public.increment_draft_count(user_id uuid)
returns table(new_count integer, user_plan text)
language plpgsql
security definer
set search_path = pg_catalog
as $function$
declare
  result_count int;
  result_plan text;
begin
  if auth.uid() is null or auth.uid() <> user_id then
    raise exception 'not authorized';
  end if;

  update public.profiles
  set
    draft_count = case
      when last_draft_date is distinct from current_date then 1
      else draft_count + 1
    end,
    last_draft_date = current_date,
    updated_at = now()
  where id = user_id
  returning draft_count, plan into result_count, result_plan;

  return query select result_count, result_plan;
end;
$function$;

revoke all on function public.increment_draft_count(uuid) from public, anon;
grant execute on function public.increment_draft_count(uuid) to authenticated, service_role;
